    In demos, 8s form vertical rails; their discontinuities define where the
    path crosses. Follow the continuous path in the 0 background, moving
    horizontally/vertically between rail openings.
    """
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    start = next(((r, c) for r in range(h) for c in range(w) if grid[r][c] == 2), None)
    if start is None:
        return out
    # The track is obtained by walking the zero corridor adjacent to 8 rails;
    # at each step continue straight if possible, otherwise turn to follow the
    # next opening. Stop upon reaching an edge or dead end.
    r, c = start
    prev = None
    seen = {start}
    while True:
        options = []
        for dr, dc in ((0,1),(1,0),(0,-1),(-1,0)):
            q = (r+dr, c+dc)
            if 0 <= q[0] < h and 0 <= q[1] < w and q not in seen and grid[q[0]][q[1]] == 0:
                options.append(q)
        if not options:
            break
        # Continue in same direction where possible; otherwise choose the
        # available zero cell bordered by the most 8 rail cells.
        if prev:
            d = (r-prev[0], c-prev[1])
            straight = (r+d[0], c+d[1])
            if straight in options:
                nxt = straight
            else:
                def score(q):
                    return sum(0 <= q[0]+dr < h and 0 <= q[1]+dc < w and grid[q[0]+dr][q[1]+dc] == 8 for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)))
                nxt = max(options, key=score)
        else:
            nxt = options[0]
        out[nxt[0]][nxt[1]] = 2
        seen.add(nxt)
        prev, (r,c) = (r,c), nxt
    return out
"
}

