    seeds = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if not seeds:
        return out
    r0, c0 = seeds[0]
    bars = [r for r in range(r0 + 1, h) if 8 in grid[r]]
    active = {c0}
    previous = r0
    for br in bars:
        gaps = [c for c,v in enumerate(grid[br]) if v == 0]
        if not gaps:
            continue
        # Each incoming ray passes through its nearest opening(s); ties branch.
        targets = set()
        for c in active:
            distance = min(abs(g-c) for g in gaps)
            targets.update(g for g in gaps if abs(g-c) == distance)
        if not targets:
            continue
        lo, hi = min(active | targets), max(active | targets)
        corridor = br - 1
        for c in range(lo, hi+1):
            if grid[corridor][c] == 0:
                out[corridor][c] = 2
        for c in targets:
            out[br][c] = 2
        for c in active:
            for r in range(previous+1, corridor):
                if grid[r][c] == 0:
                    out[r][c] = 2
        active = targets
        previous = br
    for c in active:
        for r in range(previous+1, h):
            if grid[r][c] == 0:
                out[r][c] = 2
    return out
