{
 "path": "/home/USER/continual-arc-baselines/.workbench/stage1/HPL-openclaw-luna6-low-ws0/frozen/held-out/play/users/u062/system/state/workspace/programs/task-4bba16f3.py",
 "content": "def transform(grid):
    """Extend the seed through holes in each patterned barrier, linking rails."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seed = next(((r,c) for r in range(h) for c in range(w) if grid[r][c] == 2), None)
    if seed is None:
        return out
    r0, c0 = seed
    barriers = [r for r in range(r0+1,h) if 8 in grid[r]]
    prev = [c0]
    last = r0
    for br in barriers:
        gaps = [c for c,v in enumerate(grid[br]) if v == 0]
        if not gaps:
            continue
        # Carry each incoming line to its nearest gap(s) in this barrier.
        targets=set()
        for c in prev:
            d=min(abs(c-g) for g in gaps)
            targets.update(g for g in gaps if abs(c-g)==d)
        if not targets:
            continue
        # Vertical rays through the clear band; join their endpoints in its
        # middle row to form the zigzag path demonstrated by the examples.
        for c in prev:
            for y in range(last+1,br):
                if grid[y][c]==0:
                    out[y][c]=2
        mid=(last+br)//2
        lo=min(set(prev)|targets); hi=max(set(prev)|targets)
        for c in range(lo,hi+1):
            if grid[mid][c]==0:
                out[mid][c]=2
        for c in targets:
            out[br][c]=2
        prev=sorted(targets)
        last=br
    for c in prev:
        for y in range(last+1,h):
            if grid[y][c]==0: out[y][c]=2
    return out
