{
 "path": "/home/USER/continual-arc-baselines/.workbench/stage1/HPL-openclaw-luna6-low-ws0/frozen/held-out/play/users/u062/system/state/workspace/programs/task-4bba16f3.py",
 "content": "def transform(grid):
    """Copy the missing-cell pattern of the 8 rows into the row above."""
    out=[row[:] for row in grid]
    # Each 8-pattern row is a stencil; color its missing positions 2 in the
    # immediately preceding blank row. The seed indicates the top stencil.
    for r in range(1,len(grid)):
        if 8 in grid[r]:
            for c,v in enumerate(grid[r]):
                if v==0 and grid[r-1][c]==0:
                    out[r-1][c]=2
    return out
