{
 "path": "/home/USER/continual-arc-baselines/.workbench/stage1/HPL-openclaw-luna6-low-ws0/frozen/held-out/play/users/u062/system/state/workspace/programs/task-4bba16f3.py",
 "content": "def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    seed=next(((r,c) for r in range(h) for c in range(w) if grid[r][c]==2),None)
    if seed is None: return out
    r,c=seed
    bars=[rr for rr in range(r+1,h) if 8 in grid[rr]]
    active={c}
    for br in bars:
        gaps={x for x,v in enumerate(grid[br]) if v==0}
        if not gaps: continue
        # Route each incoming line to all openings in the next barrier; the
        # horizontal segment between adjacent rails passes through the gaps.
        lo=min(active|gaps); hi=max(active|gaps)
        band=br-1
        for x in range(lo,hi+1):
            if grid[band][x]==0: out[band][x]=2
        for x in gaps: out[br][x]=2
        # carry vertical tracks through the open interval
        for x in active|gaps:
            for y in range(r+1,br-1):
                if grid[y][x]==0: out[y][x]=2
        active=gaps
        r=br
    for x in active:
        for y in range(r+1,h):
            if grid[y][x]==0: out[y][x]=2
    return out
"
}

{
 "path": "/home/USER/continual-arc-baselines/.workbench/stage1/HPL-openclaw-luna6-low-ws0/frozen/held-out/play/users/u062/system/state/workspace/programs/task-4bba16f3.py",
 "content": "def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    seed=next(((r,c) for r in range(h) for c in range(w) if grid[r][c]==2),None)
    if seed is None:return out
    r,c=seed
    active={c}
    bars=[rr for rr in range(r+1,h) if 8 in grid[rr]]
    for br in bars:
        gaps=[x for x,v in enumerate(grid[br]) if v==0]
        if not gaps:continue
        targets=set()
        for a in active:
            left=[g for g in gaps if g<a]
            right=[g for g in gaps if g>a]
            if left: targets.add(max(left))
            if right: targets.add(min(right))
            if not left and not right:
                targets.add(min(gaps,key=lambda g:abs(g-a)))
        # Connect incoming lanes to their corresponding opening(s) in the
        # blank corridor above this barrier.
        for a in active:
            for y in range(r+1,br-1):
                if grid[y][a]==0:out[y][a]=2
            for t in targets:
                for x in range(min(a,t),max(a,t)+1):
                    if grid[br-1][x]==0:out[br-1][x]=2
        for t in targets:out[br][t]=2
        r=br;active=targets
    for c in active:
        for y in range(r+1,h):
            if grid[y][c]==0:out[y][c]=2
    return out
