    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    bars=[r for r,row in enumerate(grid) if 8 in row]
    gaps={r:[c for c,v in enumerate(grid[r]) if v==0] for r in bars}
    # Extend each row's missing 8 cells as 2 tracks, joining the gaps across
    # the adjacent empty band; carry each gap vertically to the next band.
    seed=next(((r,c) for r in range(h) for c in range(w) if grid[r][c]==2),None)
    if bars:
        first=bars[0]; gs=gaps[first]
        if seed:
            lo,hi=min([seed[1]]+gs),max([seed[1]]+gs)
            for c in range(lo,hi+1):
                if grid[first-1][c]==0:out[first-1][c]=2
        for c in gs:out[first][c]=2
    for i,br in enumerate(bars):
        gs=gaps[br]
        for c in gs:out[br][c]=2
        nextbr=bars[i+1] if i+1<len(bars) else h
        ng=gaps[bars[i+1]] if i+1<len(bars) else gs
        if i+1<len(bars):
            for c in gs:
                for r in range(br+1,nextbr):
                    if grid[r][c]==0:out[r][c]=2
            # Join the horizontal range of the current and next gap sets in
            # the last blank row before the next 8 row.
            lo=min(gs+ng); hi=max(gs+ng); rr=nextbr-1
            for c in range(lo,hi+1):
                if grid[rr][c]==0:out[rr][c]=2
        else:
            for c in gs:
                for r in range(br+1,h):
                    if grid[r][c]==0:out[r][c]=2
    return out
